visible.script:
calls = 0
@retry(max_attempts=3)
def flaky():
    global calls
    calls += 1
    if calls < 3:
        raise RuntimeError("transient")
    return "ok"
assert flaky() == "ok"
assert calls == 3

count = 0
@retry(max_attempts=2)
def broken():
    global count
    count += 1
    raise ValueError("bad payload")
try:
    broken()
    assert False
except ValueError as exc:
    assert str(exc) == "bad payload"
assert count == 2

