tries = 0
@retry()
def ping():
    global tries
    tries += 1
    if tries < 2:
        raise OSError("blip")
    return 200
assert ping() == 200
assert tries == 2

hits = 0
@retry(max_attempts=3, exceptions=(TimeoutError,))
def guarded():
    global hits
    hits += 1
    raise ValueError("fatal")
try:
    guarded()
    assert False
except ValueError:
    pass
assert hits == 1

